site is the reporting checker's own code at the line that raised this finding: its conditions are what the runtime observed, and its comments, where they name a conforming route, are the checker's statement of what it accepts. policy_evidence records what the pipeline itself observed outside the code -- connecting to a server, downloading a file and computing its digests -- and is established fact, not a hypothesis to confirm."},"diagnostic_evidence":{"evidence_id":"DET-001","kind":"detector_diagnostic","trust_level":"reported_detector_output","informational_only":true,"decision_authority":"none","sha256":"9b8ce2659043299e65c7683d7ec9749ee8db051de273586d3e490fd9b65b45d7","data":{"finding_id":"org.cryptomator.data.cloud.webdav.network.DefaultTrustManager$Companion:::tryToFindDefaultTrustManager:::TrustManagerFactorySpec:::UnsatisfiedConstraint:::a null KeyStore given to TrustManagerFactory.init requests the platform default trust store, whose loading was not observed","tool":"rvsec","specification":"TrustManagerFactorySpec","message":"a null KeyStore given to TrustManagerFactory.init requests the platform default trust store, whose loading was not observed","reported_class":"org.cryptomator.data.cloud.webdav.network.DefaultTrustManager$Companion","reported_method":"tryToFindDefaultTrustManager","source_file_path":"data/src/main/java/org/cryptomator/data/cloud/webdav/network/DefaultTrustManager.kt","detector_context":{"code":"TRUSTMANAGERFACTORY-NOBS-02","site_kind":"NOBS: a required origin was not observed (not a positive contradiction)","label":"platform-default","label_meaning":"NOT OBSERVED: the runtime monitor tracks the producers a rule requires by object identity within one process, and saw none for this object. The argument was null, which the API documents as 'use the platform default' (e.g. TrustManagerFactory.init((KeyStore) null)); correct code produces this.","value":"PKIX","expected":"a KeyStore this instrumentation observed being loaded","source_location":"DefaultTrustManager.kt:55","codes":"TRUSTMANAGERFACTORY-NOBS-02 [platform-default] (1)","tools":"monkey:fast","runtime_observation":"Reported in 1 run(s) of the app; each run starts from a clean, read-only emulator.","runtime_coverage_file":"/mnt/c/Users/Antonow/Documents/tcc_v3/outputs/rvsec_lite_20261024/findings_all.coverage.json"}}},"evidence_catalog":[{"evidence_id":"SRC-001","kind":"target_source","trust_level":"repository_exact_source","mandatory":true,"sha256":"a54dbe8f4c175b29755d3992f154ded20671b044d27c687e411cc2e552f307c3","data":{"source_file_path":"data/src/main/java/org/cryptomator/data/cloud/webdav/network/DefaultTrustManager.kt","relevance":["reported finding location","call site of the target method","reviewed protected-value lifetime flow","direct call site","AST-resolved caller with matching signature"],"content":"package org.cryptomator.data.cloud.webdav.network

import org.cryptomator.data.util.X509CertificateHelper.convertToPem
import org.cryptomator.domain.exception.NotTrustableCertificateException
import java.security.KeyStore
import java.security.KeyStoreException
import java.security.NoSuchAlgorithmException
import java.security.cert.CertificateException
import java.security.cert.X509Certificate
import javax.net.ssl.TrustManagerFactory
import javax.net.ssl.X509TrustManager

internal class DefaultTrustManager : X509TrustManager {

	private val delegate: X509TrustManager = findDefaultTrustManager()

	@Throws(CertificateException::class)
	override fun checkClientTrusted(chain: Array<X509Certificate>, authType: String) {
		try {
			delegate.checkClientTrusted(chain, authType)
		} catch (e: CertificateException) {
			throw NotTrustableCertificateException(convertToPem(chain[0]), e)
		}
	}

	@Throws(CertificateException::class)
	override fun checkServerTrusted(chain: Array<X509Certificate>, authType: String) {
		try {
			delegate.checkServerTrusted(chain, authType)
		} catch (e: CertificateException) {
			throw NotTrustableCertificateException(convertToPem(chain[0]), e)
		}
	}

	override fun getAcceptedIssuers(): Array<X509Certificate> {
		return delegate.acceptedIssuers
	}

	companion object {

		private fun findDefaultTrustManager(): X509TrustManager {
			return try {
				tryToFindDefaultTrustManager()
			} catch (e: KeyStoreException) {
				throw IllegalStateException("Failed to obtain default trust manager", e)
			} catch (e: NoSuchAlgorithmException) {
				throw IllegalStateException("Failed to obtain default trust manager", e)
			}
		}

		@Throws(NoSuchAlgorithmException::class, KeyStoreException::class)
		private fun tryToFindDefaultTrustManager(): X509TrustManager {
			val trustManagerFactory = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm())

			trustManagerFactory.init(null as KeyStore?)

			trustManagerFactory.trustManagers.forEach { trustManager ->
				if (trustManager is X509TrustManager) {
					return trustManager
				}
			}

			throw IllegalStateException("Failed to obtain default trust manager: No X509TrustManager available.")
		}
	}

}
